#!/usr/bin/env node
/* Books-2 batch2 psychiatry wave: topic map only, own words, new MCQs only. */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const REF = "Psychiatry topic map (Marrow e6 topic selection only; text rewritten in own words, no verbatim copy)";
function mcq(id, q, o, a, exp, r, kp) { return { id, q, o, a, exp, r, kp }; }
function step(tx, say, vis) { return vis ? { tx, say, vis } : { tx, say, vis: null }; }
function tbl(cols, rows) { return { kind: "table", cols, rows }; }
function cmp(lt, lp, rt, rp) { return { kind: "compare", left: { title: lt, points: lp }, right: { title: rt, points: rp } }; }
const M = [];
function add(id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs) { M.push({ id, title, kb, kbName, aliases, steps, pearls, patho, diffs, invs, mcqs }); }

add("psy-sexual-gender", "Sexual dysfunction, paraphilias and gender dysphoria", "sexual_and_gender_disorders", "Sexual Dysfunction, Paraphilias and Gender Dysphoria",
 ["Sexual dysfunction", "Gender dysphoria", "Paraphilic disorders", "Erectile dysfunction"],
 [step("**Sexual dysfunction** is classified by phase: desire (hypoactive desire), arousal (erectile disorder, female arousal), orgasm (premature or delayed ejaculation, anorgasmia) and pain (genito pelvic pain penetration disorder, vaginismus, dyspareunia), needing six months pattern, distress and exclusion of medical, drug (SSRI anorgasmia, antihypertensive erectile), substance and relationship causes before psychological labelling. Erectile dysfunction in older men is a vascular sentinel needing cardiovascular risk assessment.", "Classify by phase: desire, arousal, orgasm, pain. New erection failure in older men means check heart risk. SSRIs delay orgasm."),
  step("Assessment is biopsychosocial and non judgemental: onset (lifelong versus acquired, global versus situational points psychology when situational with intact nocturnal erections), diabetes, pelvic surgery, hormones, depression and partner factors. Treatment matches cause: PDE5 inhibitors for erectile disorder (nitrate contraindication absolute), sex therapy and sensate focus, CBT, treating depression while adjusting offending antidepressants, pelvic floor work for pain disorders and couples therapy where relational.", "Situational failure with morning erections intact points psychological. PDE5 pills plus nitrates can collapse pressure: never combine."),
  step("**Gender dysphoria** is distress from incongruence between experienced gender and assigned sex (persisting at least six months in DSM pattern), distinct from nonconformity alone which is not disorder. Care follows multidisciplinary assessment, mental health support, puberty suppression in carefully assessed adolescents per local protocol, hormones and surgery for eligible persistent cases, with fertility counselling before treatment. Suicide risk and victimisation need active support regardless of treatment pathway stage.", "Dysphoria is distress from incongruence, not mere nonconformity. Support, assess carefully, counsel fertility before hormones."),
  step("**Paraphilic disorders** involve intense atypical sexual interests causing distress, impairment or harm to non consenting others: paedophilic (minors, safeguarding and legal duties dominate), exhibitionistic, voyeuristic, frotteuristic, sexual sadism or masochism with harm or distress, fetishistic and transvestic usually non disorder when consensual without distress. Risk management, CBT relapse prevention and antiandrogen or SSRI pharmacotherapy in specialist forensic care address harmful disorders; consensual adult atypical interests alone are not illness.", "Atypical interest becomes disorder with distress or non consenting harm. Child related offences trigger safeguarding and law first.", tbl(["Dysfunction phase", "Examples", "First check"], [["Desire", "Low desire both sexes", "Depression, hormones, relationship"], ["Arousal", "Erectile disorder", "Vascular risk, diabetes, drugs"], ["Orgasm", "Premature, delayed, anorgasmia", "SSRI effect, anxiety"], ["Pain", "Vaginismus, dyspareunia", "Pelvic, infection, endometriosis"]]))],
 ["Erectile dysfunction is cardiovascular sentinel in older men", "PDE5 inhibitor plus nitrate is absolute contraindication", "Gender nonconformity alone is not a disorder", "Paedophilic disorder triggers safeguarding duties"],
 "Vascular, neurogenic, endocrine and serotonergic drug influences interrupt sexual response phases, while gender identity development and atypical arousal pattern conditioning follow distinct developmental pathways requiring non conflated care.",
 ["Situational psychogenic versus organic erectile failure (nocturnal erections)", "Gender dysphoria versus body dysmorphic disorder focus", "Consensual fetish versus paraphilic disorder by consent and distress"],
 ["Cardiovascular risk, HbA1c, testosterone when indicated", "Medication review for sexual side effects", "Safeguarding and risk assessment for harmful paraphilias"],
 [mcq("bk2-psy-121", "Erectile failure only with partner but normal nocturnal and morning erections most suggests what?", ["Vascular disease", "Psychogenic (situational) erectile dysfunction", "Hypogonadism", "Prostate cancer"], 1, "Preserved nocturnal erections prove intact vascular neurogenic axis, pointing situational psychological causes (performance anxiety, relationship). Global loss including nocturnal suggests organic disease needing workup.", ["Incorrect. Vascular failure abolishes nocturnal erections too.", "Correct. Situational with intact nocturnal means psychogenic.", "Incorrect. Low testosterone reduces desire and nocturnal quality.", "Incorrect. Cancer link is via treatment effects, not this pattern."], "Morning wood present, partner failure: mind, not vessels."),
  mcq("bk2-psy-122", "Absolute contraindication to PDE5 inhibitors (sildenafil class) is concurrent use of what?", ["Statins", "Nitrates (any form)", "SSRIs", "Antihistamines"], 1, "Combined nitric oxide cGMP amplification causes profound hypotension; nitrate use (including recreational nitrites) absolutely contraindicates PDE5 inhibitors, and alpha blocker co use needs caution and spacing.", ["Incorrect. Statins combine safely.", "Correct. Nitrates plus PDE5 can collapse pressure.", "Incorrect. SSRIs affect orgasm, not this lethal interaction.", "Incorrect. Antihistamines safe."], "Sildenafil plus nitrate equals pressure crash."),
  mcq("bk2-psy-123", "New erectile dysfunction in a 58 year old smoker should prompt which assessment beyond sexual history?", ["Reassurance only", "Cardiovascular and diabetes risk assessment", "Prostatectomy referral", "Testosterone for all"], 1, "Penile arteries smaller than coronaries declare atherosclerosis earlier, so erectile dysfunction is sentinel event for cardiovascular risk stratification, lipids, pressure and glucose screening.", ["Incorrect. Misses sentinel value.", "Correct. Screen heart and diabetes risk.", "Incorrect. Surgery not indicated by symptom.", "Incorrect. Testosterone only when deficient."], "Failed erections warn of future heart attacks."),
  mcq("bk2-psy-124", "Patient develops anorgasmia after starting an SSRI. Best initial approach is what?", ["Stop antidepressant abruptly", "Discuss options: watchful adaptation, dose timing or reduction, switching agent or adjuncts with prescriber", "Add antipsychotic", "Ignore as trivial"], 1, "SSRI sexual dysfunction is common and adherence killing; shared decisions include brief adaptation wait, lowest effective dose, switching to lower risk agents (mirtazapine, bupropion patterns) or adjuncts, balancing relapse risk, never abrupt cessation.", ["Incorrect. Abrupt stop causes discontinuation and relapse.", "Correct. Shared adjustment or switch plan.", "Incorrect. Antipsychotics worsen sexual function.", "Incorrect. Dismissal breaks adherence and trust."], "Treat the side effect or lose the patient."),
  mcq("bk2-psy-125", "Gender dysphoria diagnosis centres on what, as opposed to gender nonconformity?", ["Any cross gender clothing", "Clinically significant distress from incongruence between experienced and assigned gender", "Sexual orientation", "Fertility status"], 1, "Nonconformity and orientation are not disorders; dysphoria requires marked incongruence with distress or impairment (DSM six month pattern), guiding supportive multidisciplinary care.", ["Incorrect. Clothing alone is expression, not diagnosis.", "Correct. Distress from incongruence defines dysphoria.", "Incorrect. Orientation is separate axis.", "Incorrect. Fertility counselling matters but not diagnosis."], "Distress, not difference, makes dysphoria."),
  mcq("bk2-psy-126", "Before gender affirming hormones, essential counselling includes which effect?", ["Reversible everything", "Fertility may be permanently reduced; offer preservation options", "No physical changes expected", "Mental health support prohibited"], 1, "Hormones can impair gamete production variably and sometimes permanently, so sperm or oocyte preservation discussion precedes treatment, alongside expected timelines and partial irreversibility of some changes.", ["Incorrect. Some effects persist after stopping.", "Correct. Counsel and offer fertility preservation.", "Incorrect. Changes are treatment purpose.", "Incorrect. Support accompanies all stages."], "Preserve fertility options before hormones."),
  mcq("bk2-psy-127", "A sexual interest pattern becomes paraphilic disorder when which condition applies?", ["It is statistically unusual", "It causes distress, impairment or involves non consenting harm", "Partner disapproves morally", "It begins after 30"], 1, "DSM requires distress or impairment (for non harm types) or acting with non consenting persons or minors for disorder; consensual adult atypical interests without distress are variants, not illness.", ["Incorrect. Rarity alone is not pathology.", "Correct. Distress, impairment or non consenting harm.", "Incorrect. Moral disapproval is not criterion.", "Incorrect. Age of onset does not define disorder."], "Consent and distress draw the disorder line."),
  mcq("bk2-psy-128", "Disclosure of sexual attraction to children with access to children triggers professional duty to what?", ["Keep absolute secrecy always", "Act on safeguarding: assess risk, share information per child protection duties and law, involve specialist services", "Prescribe reassurance", "Wait for offence"], 1, "Child safety overrides routine confidentiality within legal safeguarding frameworks; risk assessment, referral to specialised services and information sharing protect identifiable children, while treating non offending help seekers supportively encourages disclosure.", ["Incorrect. Safeguarding law limits confidentiality here.", "Correct. Safeguard children and refer specially.", "Incorrect. Reassurance without action endangers.", "Incorrect. Prevention precedes offences."], "Children safety outranks secrecy."),
  mcq("bk2-psy-129", "Premature ejaculation first line management combines what approaches?", ["Immediate daily SSRI for all", "Behavioural techniques (stop start, squeeze), topical anaesthesia or on demand or daily SSRI by severity and preference", "PDE5 as cure", "Surgery"], 1, "Stepped care uses behavioural training, topical agents, and serotonergic delay (dapoxetine on demand where licensed or daily SSRI off label patterns) plus psychosexual therapy addressing anxiety and partner factors.", ["Incorrect. Daily drugs are one option tier.", "Correct. Behavioural plus topical or SSRI options.", "Incorrect. PDE5 helps comorbid erectile issue only.", "Incorrect. No surgical standard exists."], "Train, numb or delay: stepped premature care."),
  mcq("bk2-psy-130", "Vaginismus and genito pelvic pain disorder management centres on what?", ["Forced examination tolerance", "Pelvic floor physiotherapy, graded dilators, psychosexual therapy and treating vulval or pelvic pathology", "Hymenectomy routinely", "Avoid all assessment"], 1, "Pain and penetration disorders combine pelvic floor overactivity, fear avoidance and local pathology; graded desensitisation, physio and psychosexual care with gynaecology treat mechanisms, never forced penetration.", ["Incorrect. Force traumatises and worsens spasm.", "Correct. Graded pelvic and psychosexual programme.", "Incorrect. Surgery rare selected only.", "Incorrect. Gentle consented assessment finds causes."], "Relax the floor gradually, never force.")]);

add("psy-eating", "Eating disorders", "eating_disorders_psych", "Eating Disorders",
 ["Anorexia nervosa", "Bulimia nervosa", "Refeeding syndrome", "Binge eating disorder"],
 [step("**Anorexia nervosa** combines restriction leading to significantly low weight, intense fear of gaining weight and body image disturbance (weight or shape overvalued, or persistent behaviour interfering with gain plus lack of recognition of seriousness). Subtypes restrict or binge purge. Medical sequelae span bradycardia, hypotension, hypothermia, amenorrhoea and low T3, lanugo, osteoporosis, electrolyte and cardiac death risk; mortality is among highest in psychiatry, largely medical and suicide. BMI grades severity in adults but children use expected body weight trajectories.", "Low weight plus terror of fat plus distorted image is anorexia. It kills medically and by suicide more than most psychiatry."),
  step("**Bulimia nervosa** cycles binge eating (large amount with loss of control) with compensatory vomiting, laxatives, fasting or exercise at least weekly for three months at normal or above weight, with dental erosion, parotid swelling, hypokalaemic alkalosis and Russell sign (knuckle callus). **Binge eating disorder** binges without compensation, associated obesity and shame. Pica, rumination and avoidant restrictive (ARFID, fear or sensory based without body image drive, common in children and autism) complete the chapter patterns.", "Normal weight binges with vomiting is bulimia: teeth, parotids and potassium betray it. ARFID fears food without body image drive."),
  step("Refeeding syndrome is the lethal trap of renutrition: insulin surge drives phosphate, potassium and magnesium intracellularly causing cardiac failure, arrhythmia and death in first days, so high risk patients (very low BMI, minimal intake over ten days, low baseline electrolytes, alcohol comorbidity) start low calories with thiamine, vitamins and daily electrolyte replacement and monitoring per local (NICE style) protocol. Weight restoration in anorexia is usually inpatient when medical instability, rapid loss or failed outpatient gain threatens life.", "Feed too fast and phosphate crashes kill. Start low, replace electrolytes daily, give thiamine."),
  step("Treatment is multidisciplinary: medical monitoring, dietetic weight restoration and psychotherapy (CBT E enhanced, family based treatment first line in adolescents, MANTRA or specialist supportive therapy in adults). Fluoxetine helps bulimia relapse prevention at higher dose patterns; no drug treats anorexia core (olanzapine modest weight adjunct evidence only). Osteoporosis needs weight restoration above oestrogen pills alone, with DEXA monitoring. Compulsory feeding under mental health law is last resort life saving frame.", "Family therapy feeds adolescents back. CBT E leads bulimia and adult care. No pill cures anorexia.", tbl(["Disorder", "Weight", "Compensation", "Signature clue"], [["Anorexia", "Significantly low", "Restriction with or without purge", "Bradycardia, lanugo, amenorrhoea"], ["Bulimia", "Normal or high", "Weekly purge behaviours", "Dental erosion, low potassium alkalosis"], ["Binge eating", "Often high", "None", "Loss of control with shame"], ["ARFID", "Low or normal", "Avoidance by fear or senses", "No body image drive"]]))],
 ["Anorexia mortality is psychiatry highest tier", "Refeeding drops phosphate: start low and monitor", "Family based treatment first for adolescents with anorexia", "Fluoxetine aids bulimia, not anorexia core"],
 "Starvation adapts metabolism downward (low T3, bradycardia) and shrinks cardiac mass, while insulin on refeeding shifts electrolytes intracellularly overwhelming depleted stores; reward and perfectionism circuits sustain restriction against homeostatic hunger.",
 ["Anorexia versus ARFID by body image drive", "Bulimia versus binge eating by compensation", "Anorexia medical instability versus stable outpatient restoration thresholds"],
 ["Weight, vitals including postural, ECG and electrolytes daily in refeeding", "Phosphate, magnesium, potassium pre and during renutrition", "DEXA for bone health in chronic low weight"],
 [mcq("bk2-psy-131", "Anorexia nervosa diagnostic triad is what?", ["Binge, purge, normal weight", "Restriction to low weight, intense fear of gain, body image disturbance", "Obesity, shame, no compensation", "Food fear without image concern"], 1, "DSM requires significantly low weight from restriction, fear of weight gain (or gain interfering behaviour) and image disturbance or failure to recognise seriousness. Others describe bulimia, binge eating and ARFID.", ["Incorrect. That is bulimia pattern.", "Correct. Low weight, fear, image disturbance.", "Incorrect. Binge disorder lacks compensation and low weight.", "Incorrect. ARFID lacks image drive."], "Thin, terrified of fat, sees fat: anorexia."),
  mcq("bk2-psy-132", "Refeeding syndrome is driven by which electrolyte crash chiefly monitored?", ["Hypercalcaemia", "Hypophosphataemia (with potassium and magnesium falls)", "Hypernatraemia", "High ferritin"], 1, "Insulin driven intracellular phosphate shift (plus potassium, magnesium) in depleted patients causes cardiac and respiratory failure days two to five; prophylactic replacement and slow calories prevent it.", ["Incorrect. Calcium not central mechanism.", "Correct. Phosphate crash leads monitoring.", "Incorrect. Sodium issues differ (water shifts).", "Incorrect. Iron stores irrelevant here."], "Phosphate plummets when feeding restarts."),
  mcq("bk2-psy-133", "Which patients qualify high risk refeeding requiring lowest starting calories and daily bloods?", ["BMI 24 after dieting week", "Very low BMI, little intake over 10 days, low baseline electrolytes or alcohol comorbidity", "All bulimia patients", "Athletes fasting one day"], 1, "NICE style criteria flag chronic depletion markers; bulimia at normal weight without depletion usually refeeds standardly. Protocols grade calories (often 5 to 10 kcal per kg start in highest risk) individually.", ["Incorrect. Near normal weight brief diet is low risk.", "Correct. Depleted, low electrolytes, prolonged minimal intake.", "Incorrect. Weight normal bulimia rarely high risk.", "Incorrect. Single day fast depletes nothing."], "Starved long and low numbers: feed slowest."),
  mcq("bk2-psy-134", "First line psychotherapy for adolescents with anorexia nervosa is what?", ["Individual CBT only", "Family based treatment (parents refeed, externalise illness)", "Psychoanalysis", "No therapy until weight normal alone"], 1, "Family based (Maudsley) treatment empowers parents to renourish while separating illness from adolescent, outperforming individual therapy in youth. Adults receive CBT E, MANTRA or specialist supportive clinical management.", ["Incorrect. Individual alone weaker in adolescents.", "Correct. Family based treatment leads youth care.", "Incorrect. Analysis lacks eating disorder evidence.", "Incorrect. Therapy accompanies restoration."], "Parents feed, illness blamed, teen absolved."),
  mcq("bk2-psy-135", "Bulimia nervosa physical signature set includes what?", ["Lanugo and bradycardia", "Dental erosion, parotid enlargement, hypokalaemic metabolic alkalosis, Russell sign", "Obesity always", "Amenorrhoea mandatory"], 1, "Acid vomiting erodes teeth (perimolysis), swells parotids, wastes chloride and potassium causing alkalosis, and knuckles scar from teeth (Russell). Weight stays normal range unlike anorexia.", ["Incorrect. Those are starvation signs.", "Correct. Vomit chemistry and trauma marks.", "Incorrect. Weight normal or fluctuating.", "Incorrect. Menses often preserved in bulimia."], "Teeth, parotids, potassium: vomiting leaves receipts."),
  mcq("bk2-psy-136", "Pharmacotherapy with best evidence in bulimia nervosa is what?", ["Olanzapine", "Fluoxetine (higher dose range) reducing binge purge cycles", "Lithium", "Benzodiazepines"], 1, "Fluoxetine around 60 mg patterns reduced bulimic episodes in trials as adjunct to CBT E; anorexia lacks effective drug for core weight restoration. Olanzapine shows only modest anorexia weight signal.", ["Incorrect. Olanzapine is anorexia adjunct research, not bulimia lead.", "Correct. Fluoxetine adjunct in bulimia.", "Incorrect. Lithium unrelated and toxic in purging dehydration.", "Incorrect. Sedatives treat nothing here."], "Bulimia gets fluoxetine help; anorexia gets food."),
  mcq("bk2-psy-137", "Anorexia bone health best intervention is what?", ["Oestrogen pill alone", "Weight restoration and nutritional rehabilitation (plus calcium, vitamin D, DEXA monitoring)", "Bisphosphonate first in teens routinely", "Exercise loading while underweight"], 1, "Energy restoration normalises hormones and bone accrual; hormone replacement without weight gain fails to restore bone, and adolescent bisphosphonates are specialist rare choices. Excess exercise worsens deficit.", ["Incorrect. Oestrogen without weight disappoints bone.", "Correct. Restore weight to restore bone.", "Incorrect. Not routine adolescent care.", "Incorrect. Loading in deficit fractures risk."], "Feed bones back, pills alone cannot."),
  mcq("bk2-psy-138", "ARFID is distinguished from anorexia by absence of what?", ["Weight loss", "Body image disturbance and fear of fatness", "Nutritional deficiency", "Food avoidance"], 1, "Avoidant restrictive intake stems from sensory aversion, fear of choking or vomiting, or low interest, causing deficiency without shape weight drive. Treatment is exposure and nutritional rehabilitation adapted to cause.", ["Incorrect. Both can lose weight.", "Correct. No body image drive in ARFID.", "Incorrect. Deficiency occurs in both.", "Incorrect. Avoidance defines ARFID itself."], "Avoids food, not fatness: ARFID."),
  mcq("bk2-psy-139", "Medical admission thresholds in anorexia prioritise which instability markers?", ["BMI alone any value", "Bradycardia, postural hypotension, hypothermia, electrolyte disturbance, rapid loss", "Patient request only", "Duration over 5 years"], 1, "Guidelines (MEED style) triage by physiology: resting bradycardia, postural drops, low temperature, syncope, electrolytes and trajectory, not BMI number alone, because deaths follow medical collapse.", ["Incorrect. BMI informs but physiology decides urgency.", "Correct. Vitals and electrolytes instability.", "Incorrect. Risk overrides preference conflicts via law when needed.", "Incorrect. Duration chronicity differs from acuity."], "Slow pulse, cold and falling over: admit medically."),
  mcq("bk2-psy-140", "Binge eating disorder differs from bulimia by what and associates with what?", ["Has vomiting; anorexia", "Binges with loss of control without regular compensation; obesity and metabolic risk", "Occurs only in teens", "Needs low weight"], 1, "BED lacks compensatory behaviours, driving weight gain and diabetes risk; CBT and structured programmes lead, with lisdexamfetamine licensed in some regions for moderate severe adults under specialist care.", ["Incorrect. Compensation absence defines separation.", "Correct. No compensation, obesity association.", "Incorrect. Adult onset common.", "Incorrect. Weight often high."], "Binge without purge equals binge eating disorder.")]);

add("psy-neurodevelopmental", "Neurodevelopmental disorders", "neurodevelopmental_disorders", "Neurodevelopmental Disorders",
 ["Autism spectrum", "ADHD", "Intellectual disability", "Tourette"],
 [step("**Neurodevelopmental disorders** begin in childhood with atypical brain development affecting communication, learning, attention, movement and social function. **Autism spectrum disorder** requires persistent social communication deficits (reciprocity, nonverbal, relationships) plus restricted repetitive patterns (stereotypies, sameness insistence, fixated interests, sensory hypo or hyper reactivity), present early though demands may unmask later, with language and intellectual levels specified separately. Girls mask (camouflage) more, delaying diagnosis.", "Autism pairs social communication difference with repetitive sensory patterns from early life. Girls hide it longer by camouflaging."),
  step("**ADHD** shows pervasive inattention and or hyperactivity impulsivity before age 12 across settings (home and school evidence mandatory) impairing function: losing things, disorganisation, fidgeting, excessive talking, interrupting and risk taking. Adult ADHD persists in majority with executive and emotional dysregulation. Stimulants (methylphenidate, lisdexamfetamine) are first line moderate severe with atomoxetine, guanfacine alternatives; baseline and follow up pulse, pressure, weight, height and cardiac family history frame safe prescribing.", "ADHD lives in two settings before twelve. Stimulants lead, with heart and growth checks built in."),
  step("**Intellectual disability** needs deficits in intellectual and adaptive functioning from developmental period, severity by adaptive support needs not IQ alone; causes include Down, fragile X (commonest inherited), fetal alcohol, and acquired insults, each needing aetiology hunt, comorbidity care (epilepsy, autism, mental illness diagnostic overshadowing vigilance) and safeguarding. Specific learning disorders isolate reading (dyslexia), writing or mathematics against otherwise adequate instruction.", "Intellectual disability grades by support needed, not IQ digits. Do not let label overshadow treatable illness."),
  step("Motor disorders complete patterns: developmental coordination disorder (clumsiness impairing life), stereotypies, and **tic disorders**: Tourette requires multiple motor plus at least one vocal tic over a year starting before 18, waxing and waning, suppressible briefly with premonitory urge. Habit reversal (CBIT) is first line for impairing tics; alpha agonists or antipsychotics serve severe cases weighing metabolic and movement harms. Most childhood tics are transient and need explanation, not medication.", "Motor plus vocal tics over a year before eighteen is Tourette. Teach habit reversal before drugs.", tbl(["Disorder", "Core deficit", "First line anchor"], [["Autism", "Social communication plus restricted patterns", "Developmental supports, communication and education plans"], ["ADHD", "Inattention, hyperactivity before 12, two settings", "Stimulants plus behavioural strategies"], ["Intellectual disability", "Intellect plus adaptive function", "Aetiology, supports, comorbidity care"], ["Tourette", "Motor and vocal tics over 1 year", "CBIT habit reversal"]]))],
 ["ADHD needs symptoms in two or more settings before 12", "Tourette equals motor plus vocal tics beyond a year", "Fragile X is commonest inherited intellectual disability", "Stimulant monitoring: pulse, BP, growth, cardiac history"],
 "Atypical synaptic development and connectivity shape social brain, executive and motor circuits early, interacting with genetic syndromes and prenatal exposures; supports alter trajectories more than late cures.",
 ["Autism versus social anxiety (developmental reciprocity versus fear)", "ADHD versus bipolar mania in youth (chronic trait versus episodes)", "Intellectual disability versus specific learning disorder breadth"],
 ["Multi informant rating scales and developmental history", "Hearing, vision, genetic testing (fragile X, microarray) by presentation", "Baseline cardiovascular and growth charting for stimulants"],
 [mcq("bk2-psy-141", "Autism diagnosis requires which two domains?", ["Language delay plus IQ low", "Social communication deficits plus restricted repetitive patterns including sensory features", "Tics plus obsession", "Inattention plus hyperactivity"], 1, "Both DSM domains must be present early (sensory reactivity sits inside restricted repetitive domain); intellectual and language abilities are specifiers, not requirements, since autism spans all IQ.", ["Incorrect. Language and IQ vary independently.", "Correct. Social communication plus restricted patterns.", "Incorrect. That mixes Tourette and OCD.", "Incorrect. Those define ADHD."], "Social difference plus repetition equals autism core."),
  mcq("bk2-psy-142", "ADHD symptom onset and setting requirements are what?", ["After 18, one setting", "Before 12, in two or more settings with impairment", "Any age, home only", "Only during exams"], 1, "DSM requires several symptoms before twelve, cross situational pervasiveness (parent and teacher evidence) and functional impairment, excluding better explanations like sleep apnoea or trauma hypervigilance.", ["Incorrect. Adult diagnosis still traces childhood onset.", "Correct. Before twelve, two settings.", "Incorrect. Single setting suggests situational causes.", "Incorrect. Exam only is anxiety pattern."], "Two settings, before twelve: ADHD rule."),
  mcq("bk2-psy-143", "First line medication class for moderate severe ADHD in children over 5 (local guidance) is what, with which monitoring?", ["Atomoxetine always first", "Stimulants (methylphenidate class); pulse, BP, weight, height, cardiac history", "Antipsychotics", "SSRIs"], 1, "Stimulants give largest effect sizes; monitoring covers appetite and growth, cardiovascular parameters, tics, sleep and misuse or diversion in adolescents. Atomoxetine suits tics, anxiety or stimulant intolerance alternatives.", ["Incorrect. Atomoxetine is alternative line.", "Correct. Stimulants first with cardiometabolic growth checks.", "Incorrect. Antipsychotics not ADHD treatment.", "Incorrect. SSRIs treat comorbidity only."], "Stimulants lead ADHD; chart pulse and growth."),
  mcq("bk2-psy-144", "Tourette syndrome criteria are what?", ["One motor tic one month", "Multiple motor plus at least one vocal tic over 1 year, onset before 18", "Vocal tics only lifelong", "Tics only under stress in adults"], 1, "Duration over a year with both modalities and childhood onset defines Tourette; transient tic disorder resolves within year and chronic single modality types sit between. CBIT precedes drugs for impairing tics.", ["Incorrect. Too brief and single.", "Correct. Motor plus vocal, year, youth onset.", "Incorrect. Vocal alone is chronic vocal tic disorder.", "Incorrect. Adult stress tics need other evaluation."], "Motor and voice, a year, before eighteen."),
  mcq("bk2-psy-145", "Commonest inherited cause of intellectual disability, with large ears, long face and macro orchidism after puberty, is what?", ["Down syndrome", "Fragile X syndrome", "Tuberous sclerosis", "Prader Willi"], 0, "Fragile X (FMR1 CGG expansion) is leading inherited intellectual disability, X linked with autistic features; Down is commonest overall but chromosomal nondisjunction, not inherited pattern.", ["Correct. Fragile X inherited lead.", "Incorrect. Down is commonest overall, not inherited.", "Incorrect. Tuberous gives seizures and skin lesions pattern.", "Incorrect. Prader Willi hyperphagia and hypotonia picture."], "Long face, big ears, fragile X."),
  mcq("bk2-psy-146", "Diagnostic overshadowing in intellectual disability means which dangerous error?", ["Over diagnosing autism", "Attributing new psychiatric or medical symptoms to the disability itself and missing treatable illness", "Giving extra support", "Testing genetics twice"], 1, "Pain, depression or psychosis presenting as behaviour change gets dismissed as just their disability, delaying treatment; baseline behaviour records and physical workup counter this bias.", ["Incorrect. Autism co occurs genuinely often.", "Correct. Missing illness by blaming disability.", "Incorrect. Support is appropriate care.", "Incorrect. Genetics not the error."], "New behaviour is illness until proven otherwise."),
  mcq("bk2-psy-147", "First line intervention for impairing Tourette tics is what?", ["Immediate antipsychotic", "Comprehensive behavioural intervention for tics (habit reversal)", "Stimulants", "Deep brain stimulation"], 1, "CBIT teaches awareness and competing responses with support, matching drug efficacy without metabolic harm; alpha2 agonists then antipsychotics follow severity, DBS is last resort adult refractory research care.", ["Incorrect. Drugs follow behavioural first line.", "Correct. Habit reversal CBIT leads.", "Incorrect. Stimulants may worsen some tics, not treat them.", "Incorrect. DBS is exceptional last line."], "Train competing response before medicating tics."),
  mcq("bk2-psy-148", "Adult ADHD presentation most often emphasises what residual features?", ["Childhood hyperactivity unchanged maximal", "Inattention, disorganisation, impulsivity and emotional dysregulation with occupational impairment", "Psychosis", "Amnesia"], 1, "Gross motor hyperactivity often internalises to restlessness while executive failure, missed deadlines, driving risk and substance comorbidity dominate adult morbidity; diagnosis still requires childhood onset evidence.", ["Incorrect. Hyperactivity usually attenuates outwardly.", "Correct. Executive and emotional adult pattern.", "Incorrect. Psychosis suggests other disorder.", "Incorrect. Memory complaint is attentional, not amnesic."], "Adult ADHD forgets deadlines, not childhood."),
  mcq("bk2-psy-149", "Autism support with strongest outcome influence in childhood centres on what?", ["Medication for core symptoms", "Early communication, educational individualisation and family support; drugs only for comorbidity", "Institutional placement", "Diet cures"], 1, "No drug treats core autism; speech and occupational therapy, structured education, parent training and treating ADHD, anxiety, epilepsy or sleep comorbidity change trajectories. Risperidone class only targets severe irritability short term in some licences.", ["Incorrect. Core symptoms lack drug therapy.", "Correct. Developmental and educational supports lead.", "Incorrect. Inclusion with support is standard.", "Incorrect. Restrictive diets lack cure evidence."], "Teach communication; medicate companions only."),
  mcq("bk2-psy-150", "Stimulant treatment in ADHD with comorbid tics requires which approach?", ["Absolute contraindication", "Individualised trial with tic monitoring; atomoxetine or guanfacine alternatives if tics worsen", "Add antipsychotic prophylaxis", "Stop all ADHD care"], 1, "Group data show stimulants do not worsen tics on average, so monitored trial is reasonable, switching to non stimulants if individual exacerbation occurs. Untreated ADHD often harms more.", ["Incorrect. Not absolute; monitor individually.", "Correct. Trial with monitoring and alternatives ready.", "Incorrect. Prophylactic antipsychotics add harm.", "Incorrect. ADHD still deserves treatment."], "Tics do not automatically ban stimulants.")]);

add("psy-antipsychotics", "Antipsychotic drugs", "antipsychotic_drugs_psych", "Antipsychotic Drugs",
 ["Typical and atypical antipsychotics", "Extrapyramidal side effects", "Neuroleptic malignant syndrome", "Clozapine monitoring"],
 [step("**Antipsychotics** all antagonise or partially agonise dopamine D2 receptors. First generation (haloperidol, chlorpromazine) cause more extrapyramidal effects; second generation (risperidone, olanzapine, quetiapine, aripiprazole partial agonist) trade toward metabolic harm variably (olanzapine and clozapine worst weight and diabetes, aripiprazole least). Choice follows patient prior response, side effect vulnerability, formulation (oral, long acting injection) and medical comorbidity, not class superiority claims except clozapine in resistance.", "All block D2. Typicals move muscles; atypicals move metabolism. Clozapine alone beats resistance."),
  step("**Extrapyramidal effects** timeline: acute dystonia (hours to days, torticollis, oculogyric crisis, treated anticholinergic like procyclidine), akathisia (days to weeks inner restlessness, dose reduce or beta blocker or benzodiazepine strategies, suicide linked distress), parkinsonism (weeks, bradykinesia, rigidity, tremor) and tardive dyskinesia (months to years, choreoathetoid orofacial movements, stop or switch, VMAT2 inhibitors treat). Anticholinergic prophylaxis is not routine given cognition and tardive worsening.", "Dystonia days, akathisia weeks, parkinsonism months early, tardive years. Akathisia feels like torture inside skin."),
  step("**Neuroleptic malignant syndrome** is rare lethal hyperdopamine blockade reaction: fever, lead pipe rigidity, confusion, autonomic instability, raised CK and leucocytosis, usually after starting or raising antipsychotics (or abrupt dopamine agonist withdrawal). Stop antipsychotic, cool, hydrate, ICU, consider dantrolene or bromocriptine and ECT in refractory cases, differentiating serotonin syndrome (clonus, hyperreflexia, serotonergic drugs, agitation) where reflexes and bowel activity surge instead.", "Fever plus lead pipe rigidity plus confusion after antipsychotic is NMS: stop drug, cool, ICU. Serotonin syndrome twitches and clonus instead."),
  step("Monitoring is treatment: baseline and periodic weight, waist, glucose or HbA1c, lipids, pressure, ECG (QT prolonging combinations), prolactin (risperidone, amisulpride, typicals raise; sexual dysfunction, amenorrhea, galactorrhoea, bone loss), movement scales and full blood count pathways for **clozapine** (neutropenia, myocarditis early, constipation ileus deaths, seizures dose related). High dose antipsychotic prescribing beyond licensed totals and polypharmacy need documented rationale and ECG vigilance, generally discouraged.", "Weigh, sugar, lipids, ECG, prolactin, movements: monitoring is half the prescription. Clozapine adds blood, heart and bowel watch.", tbl(["Adverse effect", "Timing", "Antidote direction"], [["Acute dystonia", "Hours to days", "Anticholinergic (procyclidine)"], ["Akathisia", "Days to weeks", "Dose reduce, beta blocker strategies"], ["Parkinsonism", "Weeks", "Reduce, switch, cautious anticholinergic"], ["Tardive dyskinesia", "Months to years", "Stop culprit, VMAT2 inhibitor"], ["NMS", "Days to weeks after change", "Stop, ICU, cooling, consider dantrolene"]]))],
 ["Clozapine is only drug proven in treatment resistance", "NMS: fever, rigidity, confusion, high CK; stop antipsychotic", "Olanzapine and clozapine worst metabolic; aripiprazole least", "Risperidone class prolactin highest"],
 "D2 blockade in striatum produces movement disorders while mesolimbic blockade treats psychosis; tuberoinfundibular blockade raises prolactin and hypothalamic actions drive appetite and metabolic syndrome.",
 ["NMS versus serotonin syndrome (rigidity bradyreflexia versus clonus hyperreflexia)", "Akathisia versus anxiety agitation (inner urge to move)", "Tardive dyskinesia versus withdrawal dyskinesia course"],
 ["Baseline metabolic panel, ECG, prolactin by drug", "AIMS movement examination periodically", "Clozapine FBC registration, myocarditis vigilance (CRP, troponin local protocol)"],
 [mcq("bk2-psy-151", "Boy develops torticollis and oculogyric crisis two days after haloperidol. Treatment is what?", ["Increase haloperidol", "Anticholinergic such as procyclidine (or benztropine) promptly", "Beta blocker", "ECT"], 1, "Acute dystonia is early EPS emergency (airway threatening if laryngeal) reversed by parenteral anticholinergic, then regimen review. Continuing culprit worsens it.", ["Incorrect. More blockade worsens dystonia.", "Correct. Anticholinergic reverses acute dystonia.", "Incorrect. Beta blockers suit akathisia.", "Incorrect. ECT not first for dystonia."], "Twisted neck day two: procyclidine now."),
  mcq("bk2-psy-152", "Inner restlessness, pacing, inability to sit still two weeks on antipsychotic, often misread as agitation, is what and needs what?", ["Tardive dyskinesia; more drug", "Akathisia; dose reduction or switch, beta blocker or benzodiazepine adjuncts", "Mania; lithium", "Catatonia; lorazepam only"], 1, "Akathisia is subjective motor restlessness linked to distress and suicide; raising antipsychotic for apparent agitation worsens trap. Reduce or switch culprit, propranolol or short benzodiazepine or mirtazapine strategies by guidance.", ["Incorrect. Tardive is late choreiform, not restlessness.", "Correct. Akathisia, reduce dopamine blockade burden.", "Incorrect. No elevated mood syndrome described.", "Incorrect. Catatonia is immobility spectrum opposite."], "Cannot sit inside own skin: akathisia."),
  mcq("bk2-psy-153", "Fever 39.5, lead pipe rigidity, confusion, CK 8000, one week after antipsychotic increase. Diagnosis and first step?", ["Serotonin syndrome; continue drug", "Neuroleptic malignant syndrome; stop antipsychotic, urgent medical ICU care", "Malignant catatonia only; add antipsychotic", "Sepsis alone; antipsychotic irrelevant"], 1, "NMS follows dopamine blockade with hyperthermia, rigidity, delirium, dysautonomia and muscle breakdown; immediate cessation, cooling, fluids and critical care, considering dantrolene, bromocriptine or ECT refractory. Sepsis workup parallels but drug stop cannot wait.", ["Incorrect. Serotonin has clonus and serotonergic exposure.", "Correct. NMS: stop antipsychotic, ICU.", "Incorrect. More blockade kills.", "Incorrect. Infection may coexist but NMS action is urgent."], "Hot, rigid, confused on antipsychotic: stop it."),
  mcq("bk2-psy-154", "Serotonin syndrome is separated from NMS most by which signs?", ["Fever absent", "Clonus, hyperreflexia, agitation and diarrhoea after serotonergic agents", "Lead pipe rigidity and bradyreflexia", "CK normal always"], 1, "Serotonergic excess gives neuromuscular hyperactivity (spontaneous or inducible clonus, hyperreflexia lower limbs) with hyperactive bowels, versus NMS hyporeflexic lead pipe rigidity after dopamine blockers. Both fever and confuse.", ["Incorrect. Both can fever high.", "Correct. Clonus and hyperreflexia mean serotonin.", "Incorrect. That describes NMS.", "Incorrect. CK rises in both severe cases."], "Clonus points serotonin; lead pipe points NMS."),
  mcq("bk2-psy-155", "Which antipsychotics carry greatest weight gain and diabetes risk as pair?", ["Aripiprazole, ziprasidone pattern", "Clozapine and olanzapine", "Haloperidol, amisulpride", "Quetiapine lowest"], 1, "Metabolic hierarchy places clozapine and olanzapine worst, risperidone and quetiapine intermediate, aripiprazole and ziprasidone or lurasidone patterns lower, guiding choice in obesity and diabetes risk with monitoring regardless.", ["Incorrect. Those are metabolically kinder.", "Correct. Clozapine and olanzapine worst.", "Incorrect. Typicals burden movement more than metabolism.", "Incorrect. Quetiapine is intermediate, not lowest."], "Clozapine and olanzapine feed diabetes."),
  mcq("bk2-psy-156", "Amenorrhoea, galactorrhoea and sexual dysfunction on risperidone reflect which effect and pathway?", ["QT prolongation", "Hyperprolactinaemia from tuberoinfundibular D2 blockade", "Anticholinergic dryness", "Serotonin syndrome"], 1, "Dopamine tonically inhibits prolactin; pituitary blockade raises it (risperidone, amisulpride, typicals highest; aripiprazole lowers), causing hypogonadism and bone loss needing level check and switch planning.", ["Incorrect. QT is cardiac conduction issue.", "Correct. Prolactin rise from D2 blockade.", "Incorrect. Dryness differs from galactorrhoea.", "Incorrect. No serotonergic storm pattern."], "Milky, period stopped on risperidone: prolactin."),
  mcq("bk2-psy-157", "Tardive dyskinesia management first steps are what?", ["Add anticholinergic routinely", "Review and reduce or switch culprit antipsychotic, consider VMAT2 inhibitor for persistent impairing movements", "Increase dose to mask", "Start benzodiazepine forever"], 1, "Anticholinergics worsen tardive dyskinesia; dose minimisation or clozapine switch and vesicular monoamine transporter inhibitors (valbenazine class where available) treat established cases, with prevention by lowest effective dose and AIMS monitoring.", ["Incorrect. Anticholinergics aggravate TD.", "Correct. Reduce culprit, VMAT2 inhibitor option.", "Incorrect. Masking raises dose and worsens course.", "Incorrect. Sedation not disease treatment."], "Late mouth movements: less blocker, not anticholinergic."),
  mcq("bk2-psy-158", "Clozapine early treatment vigilance beyond neutropenia must include which two lethal risks?", ["Alopecia and rash only", "Myocarditis (first weeks) and severe constipation ileus", "Diabetes insipidus", "Retinal toxicity"], 1, "Fever, chest pain, tachycardia in first months raise myocarditis needing CRP troponin pathways, while clozapine constipation kills via ileus requiring active bowel questioning and laxatives at every contact.", ["Incorrect. Skin issues minor beside these.", "Correct. Myocarditis and ileus constipation.", "Incorrect. Not clozapine signature.", "Incorrect. Retina concerns vigabatrin or phenothiazine history."], "Clozapine kills by heart inflammation and blocked bowel too."),
  mcq("bk2-psy-159", "Aripiprazole differs mechanistically as what, giving which advantages?", ["Pure antagonist; most sedation", "Dopamine partial agonist; low metabolic and prolactin lowering, but akathisia and impulse control warnings", "Serotonin only; no psychosis effect", "Irreversible blocker"], 1, "Partial agonism stabilises dopamine (antipsychotic with less hyperprolactinaemia and metabolic burden) at cost of activation, akathisia, nausea and rare impulse control disorders (gambling) counselling.", ["Incorrect. It activates partially, less sedating.", "Correct. Partial agonist profile.", "Incorrect. D2 action is core.", "Incorrect. Binding is reversible."], "Half on dopamine: kinder metabolism, restless edge."),
  mcq("bk2-psy-160", "High dose antipsychotic polypharmacy default guideline stance is what?", ["Encouraged above licensed doses", "Avoid; document exceptional rationale, ECG and monitoring if ever used, taper to monotherapy", "Required in first episode", "Replaces clozapine pathway"], 1, "Combinations raise QT, metabolic and movement harm without general efficacy gain (clozapine augmentation exceptions specialist led); guidelines demand monotherapy optimisation and clozapine for resistance instead.", ["Incorrect. Opposite of guidance.", "Correct. Avoid polypharmacy, monotherapy and clozapine pathway.", "Incorrect. First episode needs low dose single agent.", "Incorrect. Polypharmacy delays proven clozapine."], "One antipsychotic well used beats three stacked.")]);

add("psy-antidepressants-mood-stabilisers", "Antidepressants and mood stabilisers", "antidepressants_mood_stabilisers_psych", "Antidepressants and Mood Stabilisers",
 ["SSRIs SNRIs", "Serotonin syndrome", "Lithium monitoring", "Valproate teratogenicity"],
 [step("**Antidepressants** classes: SSRIs first line (sertraline post MI friendly, fluoxetine long half life and interactions, paroxetine discontinuation and weight, citalopram QT dose caps), SNRIs (venlafaxine hypertension and discontinuation), mirtazapine (sedation, appetite, low sexual effects), tricyclics (effective but cardiotoxic, anticholinergic, lethal in overdose, amitriptyline pain at low dose), MAOIs (specialist, tyramine diet, washouts). Onset takes weeks; review at two to four weeks, continue six to twelve months after first episode remission, taper slowly avoiding discontinuation syndrome (dizzy, electric shocks, irritability with short half life agents).", "SSRIs first. Weeks to work, months to stay, taper slowly. Paroxetine stops hardest; tricyclics kill in overdose."),
  step("**Serotonin syndrome** follows serotonergic stacking (SSRI plus MAOI, tramadol, linezolid, triptans context, St John wort) with mental agitation, autonomic hyperactivity and neuromuscular clonus or hyperreflexia, treated by stopping serotonergics, benzodiazepine sedation, cooling and cyproheptadine in moderate severe hospital care. Switching antidepressants respects washouts (fluoxetine five weeks before MAOI due norfluoxetine). Hyponatraemia SIADH in elderly, bleeding risk with NSAIDs or anticoagulants (platelet serotonin), and initial activation or suicidal thought monitoring in youth frame SSRI safety.", "Stack serotonergics and clonus burns: stop, sedate, cool. Fluoxetine needs five weeks before MAOI."),
  step("**Lithium** remains gold standard for bipolar prophylaxis and acute mania adjunct with anti suicide benefit, narrow therapeutic index (target ranges per local protocol, lower elderly), requiring renal, thyroid, calcium and level monitoring (12 hour post dose). Toxicity (coarse tremor, vomiting, diarrhoea, confusion, seizures) precipitates with dehydration, NSAIDs, ACE inhibitors and thiazides reducing clearance. Long term harms: hypothyroidism, hyperparathyroidism, nephrogenic diabetes insipidus and CKD surveillance, plus teratogenic cardiac risk counselling (Ebstein relative risk small absolute).", "Lithium saves bipolar lives on a knife edge: levels, kidneys, thyroid, calcium. NSAIDs and dehydration poison it."),
  step("Other mood agents: **valproate** effective mania prophylaxis but major teratogen (neural tube, neurodevelopmental) restricted in women and girls with pregnancy prevention programmes, also weight, hepatic, platelet and PCOS effects; carbamazepine (enzyme inducer, hyponatraemia, blood dyscrasias, HLA rash screening in at risk ancestries); lamotrigine prevents bipolar depression (slow titration against Stevens Johnson, valproate doubles levels); quetiapine and other atypicals span mania and bipolar depression licences. Pregnancy and breastfeeding choices are individualised specialist decisions never abrupt cessation by default.", "Valproate and pregnancy do not mix without prevention programme. Lamotrigine titrates slowly or skin falls off.", tbl(["Drug", "Bipolar strength", "Signature monitor"], [["Lithium", "Mania prophylaxis, anti suicide", "Levels, renal, thyroid, calcium"], ["Valproate", "Mania", "Teratogen rules, liver, platelets, weight"], ["Lamotrigine", "Bipolar depression prevention", "Slow titration, rash"], ["Carbamazepine", "Mania alternative", "Sodium, blood count, inducer interactions"]]))],
 ["Tricyclics lethal in overdose: avoid in high suicide risk", "Serotonin syndrome equals clonus after serotonergic stack", "Lithium toxicity follows NSAIDs, ACE inhibitors, thiazides, dehydration", "Valproate teratogenicity mandates pregnancy prevention"],
 "Monoamine modulation neuroplastically lifts mood over weeks, while lithium intracellular signalling (inositol, GSK3 pathways) stabilises circadian and mood networks; valproate epigenetic and GABA actions contrast lamotrigine glutamate sodium channel effects.",
 ["Serotonin syndrome versus NMS by exposure and reflexes", "Discontinuation syndrome versus relapse by timing and shock sensations", "Lithium tremor fine (therapeutic) versus coarse (toxic)"],
 ["12 hour lithium levels, U&E, eGFR, TFT, calcium schedule", "ECG for citalopram QT and tricyclic conduction", "Pregnancy test and prevention programme before valproate"],
 [mcq("bk2-psy-161", "Antidepressant therapeutic onset and continuation after first depressive episode remission are typically what?", ["Days; stop at response", "2 to 6 weeks onset; continue 6 to 12 months after remission", "Immediate; lifetime always", "Three months onset; stop in 2 weeks"], 1, "Early review at 2 to 4 weeks judges tolerability and trajectory, full effect by 6 weeks at adequate dose, continuation 6 to 12 months (longer recurrent) prevents relapse, then gradual taper.", ["Incorrect. Onset lags and early stop relapses.", "Correct. Weeks on, months continuation.", "Incorrect. Neither instant nor universally lifelong.", "Incorrect. Timelines inverted."], "Slow on, stay months, taper slow."),
  mcq("bk2-psy-162", "Electric shock sensations, dizziness and irritability three days after stopping paroxetine abruptly indicate what?", ["Relapse of depression", "Antidepressant discontinuation syndrome", "Serotonin syndrome", "Mania"], 1, "Short half life agents (paroxetine, venlafaxine) cause discontinuation symptoms within days (FINISH pattern) resolving on reinstatement and slower taper, unlike relapse emerging weeks later with original symptoms.", ["Incorrect. Relapse takes weeks and lacks shocks.", "Correct. Discontinuation syndrome.", "Incorrect. No serotonergic excess or clonus.", "Incorrect. No elevated mood syndrome."], "Zap sensations after abrupt stop equals discontinuation."),
  mcq("bk2-psy-163", "Which antidepressant is most dangerous in overdose and avoided where suicide risk high?", ["Sertraline", "Amitriptyline (tricyclics)", "Mirtazapine", "Vortioxetine pattern"], 1, "Tricyclics block cardiac sodium channels causing arrhythmia, seizures and death in small multiples of daily dose, so safer SSRIs are chosen in risky patients and quantities limited.", ["Incorrect. SSRIs relatively safe in overdose.", "Correct. Tricyclics kill in overdose.", "Incorrect. Mirtazapine overdose mainly sedates.", "Incorrect. Newer agents safer profile."], "Tricyclic bottle can be a lethal weapon."),
  mcq("bk2-psy-164", "Agitation, fever, diarrhoea, tremor and inducible clonus after adding tramadol to SSRI indicates what and first action?", ["NMS; add antipsychotic", "Serotonin syndrome; stop serotonergic agents, benzodiazepine and supportive cooling", "Withdrawal; double SSRI", "Sepsis only"], 1, "Serotonergic stacking produces hyperactive neuromuscular signs distinct from NMS; cessation, sedation, fluids and temperature control with cyproheptadine for moderate severe cases in monitored settings treats it.", ["Incorrect. Exposure and clonus say serotonin.", "Correct. Stop serotonergics and sedate cool.", "Incorrect. Doubling worsens toxicity.", "Incorrect. Sepsis may mimic but drug timing directs action."], "Clonus after tramadol plus SSRI: stop both."),
  mcq("bk2-psy-165", "Required washout between stopping fluoxetine and starting an MAOI is about what and why?", ["24 hours; short action", "Five weeks; long lived norfluoxetine metabolite", "No washout", "Six months"], 1, "Norfluoxetine persists weeks, so MAOI within five weeks risks serotonin syndrome; most other SSRI to MAOI gaps are about two weeks per specific guidance.", ["Incorrect. Fluoxetine lingers longest.", "Correct. Five weeks for fluoxetine.", "Incorrect. Combination can be fatal.", "Incorrect. Six months overshoots guidance."], "Fluoxetine ghost lasts five weeks."),
  mcq("bk2-psy-166", "Lithium level sampling standard timing is what?", ["Random any time", "About 12 hours after last dose at steady state", "Immediately after dose", "Monthly trough unrelated to dose"], 1, "Twelve hour standardised levels make results comparable for narrow index dosing, checked after dose changes (about a week steady state) and during illness, dehydration or interacting drug starts.", ["Incorrect. Random levels mislead.", "Correct. Twelve hour post dose level.", "Incorrect. Peak falsely alarms.", "Incorrect. Timing anchored to dose matters."], "Twelve hours after pill, lithium tells truth."),
  mcq("bk2-psy-167", "Which co prescriptions commonly precipitate lithium toxicity by reducing clearance?", ["Paracetamol", "NSAIDs, ACE inhibitors and thiazides (plus dehydration)", "Statins", "Inhalers"], 1, "Renal prostaglandin or sodium handling changes raise lithium reabsorption; sick day rules pause lithium during vomiting, diarrhoea or poor intake with urgent level and renal checks.", ["Incorrect. Paracetamol safe analgesic here.", "Correct. NSAID, ACE inhibitor, thiazide triad.", "Incorrect. Statins no clearance effect.", "Incorrect. Inhalers unrelated."], "Painkillers, pressure pills and water pills poison lithium."),
  mcq("bk2-psy-168", "Long term lithium monitoring must include which organ systems besides levels?", ["Lungs only", "Renal function, thyroid and calcium (parathyroid)", "Liver only", "Eyes only"], 1, "Hypothyroidism, hyperparathyroidism hypercalcaemia and renal impairment (including nephrogenic diabetes insipidus polyuria) accrue over years, needing scheduled TFT, calcium and eGFR with urine symptoms review.", ["Incorrect. Pulmonary not lithium target.", "Correct. Kidney, thyroid, calcium trio.", "Incorrect. Hepatic is valproate focus.", "Incorrect. Eye exams not lithium schedule core."], "Lithium watches kidney, thyroid, calcium."),
  mcq("bk2-psy-169", "Valproate in a 19 year old woman requires what mandatory safeguard?", ["No discussion needed", "Pregnancy prevention programme: teratogenicity counselling, contraception and annual specialist review per regulations", "Folic acid alone suffices", "Only avoid in third trimester"], 1, "Valproate causes neural tube defects and neurodevelopmental harm with high absolute risks, so regulators require documented counselling, effective contraception and specialist annual acknowledgement in women of childbearing potential, preferring alternatives.", ["Incorrect. Safeguard is mandatory.", "Correct. Prevention programme required.", "Incorrect. Folate does not neutralise risk.", "Incorrect. First trimester organogenesis is critical."], "Valproate plus possible pregnancy needs programme lock."),
  mcq("bk2-psy-170", "Lamotrigine titration must be slow primarily to prevent what, and valproate does what to its level?", ["QT prolongation; lowers level", "Stevens Johnson syndrome; valproate inhibits metabolism doubling levels (halve dose)", "Agranulocytosis; no effect", "Weight gain; raises glucose"], 1, "Rapid escalation risks serious rash including Stevens Johnson, so slow schedules with valproate co therapy halved (glucuronidation inhibition) and stopped urgently for concerning rash with systemic features.", ["Incorrect. QT is citalopram concern.", "Correct. Rash prevention; valproate doubles lamotrigine.", "Incorrect. Blood dyscrasia is carbamazepine or clozapine.", "Incorrect. Lamotrigine weight neutral generally."], "Slow lamotrigine, half with valproate, watch skin.")]);

let fail = 0;
for (const m of M) {
  for (const s of m.steps) if (!s.tx.includes("**")) s.tx = "**Key point.** " + s.tx;
  const lesson = { v: 1, module: m.id, subject: "psychiatry", title: m.title, minutes: 6, steps: m.steps, quiz: m.mcqs.map((x) => x.id), src: [], refs: [REF], gen: "AI", run: "books2-batch2-psychiatry", model: "muse-wonder (local authoring, no external API)", checks: { shape: true, numbers: true, drugs: true, verbatim: true, dashes: true, verify: true, redone: 0, dropped: 0, kbWords: 0, itemN: 10 } };
  const probs = LP.checkLesson(lesson);
  if (probs.length) { console.log("LESSON FAIL", m.id, probs); fail++; }
  fs.writeFileSync(path.join(ROOT, "prep/lessons/v1", m.id + ".json"), JSON.stringify(lesson, null, 1));
  const kb = { id: m.kb, name: m.kbName, aliases: m.aliases, class: "non_infective", system: "Psychiatry", specialty: "Psychiatry", referenceOnly: true, review: { status: "ai_drafted" }, reference: { source: REF, sourceEdition: "Topic map (2026-10-13)", pages: null, clinicalPearls: m.pearls, pathophysiology: m.patho, additionalDifferentials: m.diffs, additionalInvestigations: m.invs } };
  fs.writeFileSync(path.join(ROOT, "kb/reference", m.kb + ".json"), JSON.stringify(kb, null, 1));
  const overlay = { topic: m.id, set: "maikbook2", v: 1, items: m.mcqs.map((x) => ({ prov: "SMD", gen: "hand", set: "maikbook2", d: 2, cog: "application", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against standard peer references" } } }, id: x.id, q: x.q, o: x.o, a: x.a, exp: x.exp, r: x.r, kp: x.kp })) };
  const dir = path.join(ROOT, "prep/overlays/maikbook2/psychiatry");
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, m.id + ".json"), JSON.stringify(overlay, null, 1));
}
const ixPath = path.join(ROOT, "prep/lessons/v1/index.json");
const ix = JSON.parse(fs.readFileSync(ixPath, "utf8"));
for (const m of M) ix.modules[m.id] = { title: m.title, minutes: 6, steps: m.steps.length, gen: "AI" };
fs.writeFileSync(ixPath, JSON.stringify(ix, null, 1));
const ocPath = path.join(ROOT, "prep/bank/overlay-counts.json");
const oc = JSON.parse(fs.readFileSync(ocPath, "utf8"));
oc.sets.maikbook2 = oc.sets.maikbook2 || {}; oc.sets.maikbook2.psychiatry = oc.sets.maikbook2.psychiatry || {};
for (const m of M) oc.sets.maikbook2.psychiatry[m.id] = 10;
fs.writeFileSync(ocPath, JSON.stringify(oc, null, 1));
console.log("modules:", M.length, "mcqs:", M.reduce((n, m) => n + m.mcqs.length, 0), "lesson failures:", fail);
if (fail) process.exit(1);
